const S=(()=>{let log=[],fav=[];try{log=JSON.parse(localStorage.getItem('fishora_journal_v1')||'[]');if(!Array.isArray(log))log=[]}catch{}try{fav=JSON.parse(localStorage.getItem('fishora_fav_v1')||'[]');if(!Array.isArray(fav))fav=[]}catch{}return {lat:48.8156,lon:2.496,place:'Marne · France',example:true,env:'fresh',page:'home',species:'perch',style:'shore',weather:null,marine:null,spots:[],selectedSpot:null,day:0,map:null,mapCenter:null,mapMarkers:[],mapCurrent:null,loading:false,geoLoading:false,journal:log,favs:fav,spotFetchCounter:0,observations:[],observationFetchCounter:0,observationState:'loading'};})();
const EXAMPLES=[{name:'Paris · France',lat:48.8566,lon:2.3522,env:'fresh'},{name:'Bassin d’Arcachon · France',lat:44.664,lon:-1.164,env:'sea'},{name:'Marseille · France',lat:43.2965,lon:5.3698,env:'sea'},{name:'Montréal · Canada',lat:45.5017,lon:-73.5673,env:'fresh'},{name:'Miami · États-Unis',lat:25.7617,lon:-80.1918,env:'sea'},{name:'Tokyo · Japon',lat:35.6762,lon:139.6503,env:'sea'},{name:'Sydney · Australie',lat:-33.8688,lon:151.2093,env:'sea'},{name:'Dakar · Sénégal',lat:14.7167,lon:-17.4677,env:'sea'},{name:'Bangkok · Thaïlande',lat:13.7563,lon:100.5018,env:'sea'},{name:'Rio de Janeiro · Brésil',lat:-22.9068,lon:-43.1729,env:'sea'},{name:'Reykjavík · Islande',lat:64.1466,lon:-21.9426,env:'sea'}];
let toastTimer=null, searchSeq=0, weatherSeq=0;
function toast(msg){const e=$('toast');e.textContent=msg;e.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>e.classList.remove('show'),3800)}
function setAPI(text,isOnline=false,isError=false){const e=$('apiStatus');e.className='connection'+(isOnline?' online':isError?' error':'');e.querySelector('span').textContent=text}
function pickSpeciesOptions(){return SPECIES.filter(s=>s.env===S.env||s.env==='both')}
function activeSpecies(){return SPECIES.find(s=>s.id===S.species)||SPECIES[0]}
function updateSelectors(){const allowed=pickSpeciesOptions();if(!allowed.some(s=>s.id===S.species))S.species=S.env==='sea'?'seabass':'perch';for(const selId of ['homeSpecies','forecastSpecies','tacticSpecies']){const el=$(selId);el.innerHTML=allowed.map(s=>`<option value="${s.id}">${safe(s.name)}</option>`).join('');el.value=S.species}}
function setEnv(env,quiet=false){S.env=env;document.querySelectorAll('#waterMode button').forEach(b=>b.classList.toggle('sel',b.dataset.env===env));updateSelectors();S.marine=null; if(!quiet){loadWeather();loadSpots()}else renderAll()}
function page(name){S.page=name;document.querySelectorAll('.page').forEach(e=>e.classList.toggle('active',e.id==='view-'+name));document.querySelectorAll('[data-page]').forEach(e=>e.classList.toggle('active',e.dataset.page===name));window.scrollTo({top:0,behavior:'smooth'});if(name==='explore')initMap();renderAll()}
function openModal(html){$('modalContent').innerHTML=html;$('modalBackdrop').hidden=false;hydrateIcons($('modalContent'));}
function closeModal(){$('modalBackdrop').hidden=true;$('modalContent').innerHTML=''}
function showLocation(){openModal(`<span class="section-eyebrow">DESTINATION SANS FRONTIÈRES</span><h2>Où allons-nous pêcher ?</h2><p>Recherchez une ville, un littoral ou un secteur. Vous pouvez aussi utiliser votre GPS partout dans le monde.</p><button id="modalGPS" class="primary-small" style="width:100%;margin-top:12px">${ico('locate-fixed')} Me localiser maintenant</button><div class="modal-search"><input id="placeSearch" class="text-input" placeholder="Ex. Lisbonne, lac Léman, Tokyo…" autocomplete="off"><button class="primary-small" id="doSearch">${ico('search')} Chercher</button></div><div class="search-results" id="searchResults"></div><span class="section-eyebrow" style="display:block;margin-top:20px">DESTINATIONS RAPIDES</span><div class="quick-cities">${EXAMPLES.map((e,i)=>`<button data-example="${i}">${safe(e.name.split(' · ')[0])}</button>`).join('')}</div><div class="modal-help">La géolocalisation nécessite votre autorisation et peut nécessiter HTTPS. Votre position est envoyée aux services météo et cartographiques pour fournir les données du lieu, sans compte utilisateur.</div>`);
$('modalGPS').onclick=geoLocate;$('doSearch').onclick=searchPlace;$('placeSearch').onkeydown=e=>{if(e.key==='Enter')searchPlace()};$('modalContent').querySelectorAll('[data-example]').forEach(b=>b.onclick=()=>{const p=EXAMPLES[Number(b.dataset.example)];chooseLocation(p.lat,p.lon,p.name,p.env)})}
async function searchPlace(){const q=$('placeSearch')?.value.trim();if(!q||q.length<2){toast('Saisissez un lieu à rechercher.');return}const seq=++searchSeq;$('searchResults').innerHTML='<div class="empty-lite">Recherche géographique mondiale…</div>';let places=[];try{const url='https://photon.komoot.io/api/?q='+encodeURIComponent(q)+'&limit=7&lang=fr';const r=await fetchTimed(url,14000);const j=await r.json();places=(j.features||[]).map(x=>({lat:x.geometry?.coordinates?.[1],lon:x.geometry?.coordinates?.[0],name:[x.properties?.name,x.properties?.city,x.properties?.state,x.properties?.country].filter((a,i,arr)=>a&&arr.indexOf(a)===i).join(' · ')})).filter(x=>Number.isFinite(x.lat)&&Number.isFinite(x.lon))}catch{}if(!places.length){try{const r=await fetchTimed('https://geocoding-api.open-meteo.com/v1/search?name='+encodeURIComponent(q)+'&count=7&language=fr&format=json',12000);const j=await r.json();places=(j.results||[]).map(x=>({lat:x.latitude,lon:x.longitude,name:[x.name,x.admin1,x.country].filter(Boolean).join(' · ')}))}catch{}}if(seq!==searchSeq)return;const container=$('searchResults');if(!container)return;if(!places.length){container.innerHTML='<div class="empty-lite">Aucun lieu trouvé ou service indisponible. Vous pouvez sélectionner une destination rapide ou utiliser votre GPS.</div>';return}container.innerHTML=places.map((p,i)=>`<button class="result-item" data-result="${i}">${ico('map-pin')}<span>${safe(p.name)}<small>${fmt(p.lat,4)}°, ${fmt(p.lon,4)}°</small></span></button>`).join('');container.querySelectorAll('[data-result]').forEach(b=>b.onclick=()=>{const p=places[Number(b.dataset.result)];chooseLocation(p.lat,p.lon,p.name)})}
function chooseLocation(lat,lon,name,env){if(!Number.isFinite(lat)||!Number.isFinite(lon)||Math.abs(lat)>90||Math.abs(lon)>180){toast('Coordonnées géographiques invalides.');return}S.lat=lat;S.lon=lon;S.place=name||`Position ${fmt(lat,3)}°, ${fmt(lon,3)}°`;S.example=false;S.selectedSpot=null;closeModal();if(env&&env!==S.env){setEnv(env,true)}$('placeLabel').textContent=S.place;$('locationSubtitle').textContent=`${fmt(lat,3)}° · ${fmt(lon,3)}° · ${S.env==='sea'?'Mer & océan':'Eau douce'}`;$('miniPlace').textContent=S.place.toUpperCase().slice(0,30);renderLocalExpert();loadWeather();loadSpots();loadObservations();syncMap(true);toast('Position sélectionnée · analyse en cours')}
async function geoLocate(){if(!navigator.geolocation){toast('La géolocalisation est indisponible dans ce navigateur.');return}if(S.geoLoading)return;S.geoLoading=true;toast('Autorisez la localisation précise si votre navigateur le demande.');navigator.geolocation.getCurrentPosition(async pos=>{S.geoLoading=false;const {latitude:lat,longitude:lon}=pos.coords;let name=`GPS · ${fmt(lat,3)}°, ${fmt(lon,3)}°`;try{const r=await fetchTimed(`https://nominatim.openstreetmap.org/reverse?format=json&zoom=10&lat=${lat}&lon=${lon}&accept-language=fr`,9000);if(r.ok){const j=await r.json();const a=j.address||{};name=[a.city||a.town||a.village||a.municipality||a.county||'Ma position',a.country].filter(Boolean).join(' · ')}}catch{}chooseLocation(lat,lon,name)},err=>{S.geoLoading=false;const m=err.code===1?'Autorisation GPS refusée. Utilisez la recherche de lieu.':err.code===3?'GPS indisponible dans le délai prévu.':'Position inaccessible. Choisissez une destination.';toast(m)},{enableHighAccuracy:true,timeout:13000,maximumAge:60000})}
async function fetchTimed(url,ms=15000,options={}){const ctrl=new AbortController();const tm=setTimeout(()=>ctrl.abort(),ms);try{const r=await fetch(url,{...options,signal:ctrl.signal});if(!r.ok)throw Error(`HTTP ${r.status}`);return r}finally{clearTimeout(tm)}}
async function loadWeather(){const seq=++weatherSeq;S.loading=true;setAPI('Chargement des prévisions');$('forecastUpdated').textContent='Actualisation…';const pos=`latitude=${encodeURIComponent(S.lat)}&longitude=${encodeURIComponent(S.lon)}`;const url=`https://api.open-meteo.com/v1/forecast?${pos}&current=temperature_2m,wind_speed_10m,wind_gusts_10m,weather_code,pressure_msl&hourly=temperature_2m,precipitation_probability,precipitation,wind_speed_10m,wind_gusts_10m,wind_direction_10m,pressure_msl,cloud_cover,weather_code&daily=sunrise,sunset&forecast_days=7&timezone=auto`;
try{const r=await fetchTimed(url,18000);const j=await r.json();if(seq!==weatherSeq)return;if(j.error||!j.hourly||!Array.isArray(j.hourly.time))throw Error('Données météo manquantes');S.weather=j;S.loading=false;setAPI('Prévisions synchronisées',true);$('forecastUpdated').textContent='Prévisions actualisées · '+new Date().toLocaleTimeString('fr-FR',{hour:'2-digit',minute:'2-digit'});renderAll();if(S.env==='sea')loadMarine(seq);else{S.marine=null;renderAll()}}catch(e){if(seq!==weatherSeq)return;S.weather=null;S.marine=null;S.loading=false;setAPI('Prévisions indisponibles',false,true);$('forecastUpdated').textContent='Prévisions indisponibles';renderAll();toast('Connexion aux prévisions impossible. Vérifiez Internet puis réessayez.')}}
async function loadMarine(seq){const pos=`latitude=${encodeURIComponent(S.lat)}&longitude=${encodeURIComponent(S.lon)}`;const url=`https://marine-api.open-meteo.com/v1/marine?${pos}&hourly=wave_height,wave_period,swell_wave_height,sea_surface_temperature,ocean_current_velocity,sea_level_height_msl&forecast_days=7&timezone=auto&cell_selection=sea`;try{const r=await fetchTimed(url,15000);const j=await r.json();if(seq!==weatherSeq||S.env!=='sea')return;S.marine=j?.hourly?j:null;renderAll()}catch{if(seq!==weatherSeq)return;S.marine=null;renderAll()}}
function hourlyIndices(dayOffset=S.day){const h=S.weather?.hourly;if(!h)return[];const dates=[...new Set(h.time.map(t=>t.slice(0,10)))];const selected=dates[limit(dayOffset,0,dates.length-1)];return h.time.map((s,i)=>s.slice(0,10)===selected?i:-1).filter(i=>i>=0)}
function hourAt(idx){return S.weather?.hourly?.time?.[idx]?.slice(11,16)||'—'}
function getMarineAt(idx,varName){if(!S.marine?.hourly?.time||!S.weather?.hourly?.time)return null;const t=S.weather.hourly.time[idx];let pos=S.marine.hourly.time.indexOf(t);if(pos<0){pos=S.marine.hourly.time.findIndex(x=>x.slice(0,13)===t?.slice(0,13))}const val=pos>=0?S.marine.hourly[varName]?.[pos]:null;return Number.isFinite(val)?val:null}
function dayBoundary(idx){const h=S.weather?.hourly;if(!h)return null;const d=h.time[idx].slice(0,10);const n=S.weather.daily?.time?.indexOf(d);if(n<0)return null;const sun=S.weather.daily;return{sunrise:sun.sunrise?.[n]?.slice(11,16),sunset:sun.sunset?.[n]?.slice(11,16)}}
function minuteOf(h){if(!h||!h.includes(':'))return 0;const [a,b]=h.split(':').map(Number);return a*60+b}
function scoreAt(idx){const h=S.weather?.hourly;if(!h||idx<0||idx>=h.time.length)return null;const sp=activeSpecies();let score=55;const t=minuteOf(hourAt(idx)),sun=dayBoundary(idx),rise=minuteOf(sun?.sunrise),set=minuteOf(sun?.sunset);const rangeRise=Math.abs(t-rise),rangeSet=Math.abs(t-set);const light=(t>=rise&&t<=set),golden=Math.min(rangeRise,rangeSet)<=90;
if(sp.timing==='dawn'||sp.timing==='dusk'){score+=golden?19:light?3:1;if(!light&&!golden)score-=4}else if(sp.timing==='day'){score+=light?9:-12;if(golden)score+=3}
const wind=h.wind_speed_10m?.[idx];if(Number.isFinite(wind)){score+=wind>=4&&wind<=18?8:wind<4?3:wind<=26?0:wind<=36?-12:-31}
const gust=h.wind_gusts_10m?.[idx];if(Number.isFinite(gust)&&gust>=45)score-=25;
const rain=h.precipitation?.[idx];if(Number.isFinite(rain))score+=rain===0?5:rain<1?3:rain<=3?-4:rain<=6?-15:-26;
const cloud=h.cloud_cover?.[idx];if(Number.isFinite(cloud))score+=cloud>=45&&cloud<=90?5:cloud<15?0:2;
const p=h.pressure_msl?.[idx],prev=h.pressure_msl?.[Math.max(0,idx-3)];if(Number.isFinite(p)&&Number.isFinite(prev)){const dp=p-prev;score+=Math.abs(dp)<1?5:Math.abs(dp)<3?2:-6}
const code=h.weather_code?.[idx];if(Number.isFinite(code)&&code>=95)score-=45;
if(S.env==='sea'){const wave=getMarineAt(idx,'wave_height');if(Number.isFinite(wave))score+=wave<.3?5:wave<1?8:wave<=1.5?3:wave<=2.2?-14:-37}
return Math.round(limit(score,0,100))}
function scoreLabel(x){return x>=80?'Très favorables':x>=65?'Favorables':x>=48?'Intermédiaires':x>=32?'Peu favorables':'Défavorables'}
function nowIndex(){const h=S.weather?.hourly;if(!h)return 0;const locale=new Date().toLocaleString('sv-SE',{timeZone:S.weather.timezone||'UTC',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit'}).replace(' ','T');let idx=h.time.findIndex(t=>t.startsWith(locale));if(idx<0){idx=h.time.findIndex(t=>t>=locale);if(idx<0)idx=0}return idx}
function bestIndices(limitHours=48){if(!S.weather)return[];const n=nowIndex(),h=S.weather.hourly;return Array.from({length:Math.min(limitHours,h.time.length-n)},(_,k)=>k+n).map(i=>({i,score:scoreAt(i)})).filter(x=>Number.isFinite(x.score)).sort((a,b)=>b.score-a.score)}
function bestWindowText(){const best=bestIndices()[0];if(!best)return{time:'—',desc:'Prévisions manquantes'};const start=S.weather.hourly.time[best.i];const dt=start.slice(0,10);const today=S.weather.hourly.time[nowIndex()]?.slice(0,10);const prefix=dt===today?'Aujourd’hui':dt===new Date(new Date(today+'T12:00:00').getTime()+86400000).toISOString().slice(0,10)?'Demain':formatDate(dt);return{time:hourAt(best.i),desc:`${prefix} · indice ${best.score}/100`}}
function formatDate(date){return new Date(date+'T12:00:00').toLocaleDateString('fr-FR',{weekday:'short',day:'numeric',month:'short'})}
function forecastStatus(){const cur=S.weather?.current;return cur||{}}
function renderMetrics(){const weather=S.weather;const best=bestWindowText();const now=nowIndex(),sc=scoreAt(now),cur=forecastStatus();$('mainScore').textContent=sc===null?'—':sc;$('mainScoreBar').style.width=(sc??0)+'%';$('scoreQual').textContent=sc!==null?scoreLabel(sc)+' · indicateur heuristique':'En attente de prévisions';$('bestWindow').textContent=best.time;$('bestWindowDesc').textContent=best.desc;$('mainWind').textContent=fmt(cur.wind_speed_10m);$('windDesc').textContent=Number.isFinite(cur.wind_gusts_10m)?`Rafales ${fmt(cur.wind_gusts_10m)} km/h · prévues`:'Vent prévu à 10 m';const marineWave=getMarineAt(now,'wave_height');$('fourthMetricLabel').textContent=S.env==='sea'?'Houle / vagues':'Température de l’air';$('fourthMetricValue').textContent=S.env==='sea'?(marineWave===null?'—':fmt(marineWave,1)):fmt(cur.temperature_2m);$('fourthMetricUnit').textContent=S.env==='sea'?'m':'°C';$('fourthMetricDesc').textContent=S.env==='sea'?(marineWave!==null?'Modèle marin · non navigable':'Donnée marine non disponible'):'Température météo · non de l’eau';if(weather){$('heroMessage').textContent=`${S.place} · ${scoreLabel(sc).toLowerCase()} pour ${activeSpecies().name.toLowerCase()}. Consultez le plan d’approche et les horaires à privilégier.`;const coords=document.querySelector('.hero-coordinates');coords.textContent=`${fmt(Math.abs(S.lat),1)}° ${S.lat>=0?'N':'S'}  /  ${fmt(Math.abs(S.lon),1)}° ${S.lon>=0?'E':'O'}`}}
function makeChart(indices,tall=false){if(!S.weather||indices.length<2)return'<div class="empty-state">Prévision indisponible</div>';const width=750,height=tall?270:180,left=29,right=16,top=22,bottom=35, w=width-left-right,h=height-top-bottom;const values=indices.map(i=>scoreAt(i)),dx=w/(indices.length-1);const pt=(j,sc)=>`${left+j*dx},${top+h-(sc/100)*h}`;const line=values.map((sc,j)=>pt(j,sc)).join(' ');const polygon=`${left},${top+h} ${line} ${left+w},${top+h}`;const markerInterval=tall?3:4;const nums=[25,50,75,100].map(y=>`<line class="chart-gridline" x1="${left}" x2="${width-right}" y1="${top+h-(y/100)*h}" y2="${top+h-(y/100)*h}"/><text class="chart-label" x="${left-5}" y="${top+h-(y/100)*h+3}" text-anchor="end">${y}</text>`).join('');const labels=indices.map((i,j)=>j%markerInterval===0?`<text class="chart-label" x="${left+j*dx}" y="${height-10}" text-anchor="middle">${safe(hourAt(i))}</text>`:'').join('');const dots=indices.map((i,j)=>j%markerInterval===0?`<circle cx="${left+j*dx}" cy="${top+h-(values[j]/100)*h}" r="3.2" fill="#fff" stroke="#11a99a" stroke-width="2"><title>${safe(S.weather.hourly.time[i])} · ${values[j]}/100</title></circle>`:'').join('');return`<svg viewBox="0 0 ${width} ${height}" class="chart-svg" role="img" aria-label="Indice de conditions de pêche de 0 à 100 sur la période"><defs><linearGradient id="areaGradient${tall?'b':'a'}" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="#3ac7b5" stop-opacity=".29"/><stop offset="100%" stop-color="#3ac7b5" stop-opacity=".012"/></linearGradient></defs>${nums}<polygon points="${polygon}" fill="url(#areaGradient${tall?'b':'a'})"/><polyline points="${line}" fill="none" stroke="#0dad9b" stroke-width="3" stroke-linejoin="round" stroke-linecap="round"/>${dots}${labels}</svg>`}
function renderHomeChart(){const indices=Array.from({length:24},(_,i)=>nowIndex()+i).filter(i=>i<(S.weather?.hourly?.time?.length||0));$('homeChart').classList.remove('empty-state');$('homeChart').innerHTML=makeChart(indices);$('chartSummary').textContent=S.weather?'Aperçu à partir de maintenant · indice sur 100':'Prévisions indisponibles : sélectionnez un lieu ou actualisez.'}
function renderHomeTactics(){const sp=activeSpecies();$('homeTactic').innerHTML=`<div class="preview-head"><strong>${safe(sp.rig)}</strong><span>${safe(sp.group)}</span></div><div class="preview-subtitle">${safe(sp.approach)}</div><div class="preview-attrs"><div><span>Profondeur de prospection*</span><strong>${safe(sp.depth)}</strong></div><div><span>Leurre / appât</span><strong>${safe(sp.bait)}</strong></div></div><div style="font-size:9px;color:#90a5aa;margin-top:11px">*Fourchette générique, pas une mesure bathymétrique.</div>`}
function renderHomeSpots(){const list=S.spots.slice(0,3);$('homeSpots').innerHTML=list.length?list.map((s,i)=>`<div class="spot-mini-item"><div><strong>${safe(s.name)}</strong><small>${safe(s.type)} · ${fmt(s.distance,1)} km</small></div><span>${ico('arrow-up-right')}</span></div>`).join(''):'<div class="empty-lite">Aucun secteur cartographique identifié à proximité, ou recherche indisponible.</div>'}
function renderInsights(){const sp=activeSpecies(),wind=S.weather?.current?.wind_speed_10m,code=S.weather?.current?.weather_code;let items=[['target','Zone à prospecter',sp.approach],['waves','Stratégie',sp.note]];if(Number.isFinite(wind)&&wind>28)items.unshift(['alert','Vent significatif',`Vent prévu de ${fmt(wind)} km/h. Évaluez les risques sur place avant toute sortie.`]);if(Number.isFinite(code)&&code>=95)items.unshift(['alert','Orage signalé','Risque d’orage dans les conditions météo : reportez toute sortie exposée.']);if(S.env==='sea')items.push(['shield-check','Conditions marines','Marées, courants et vagues restent des estimations : jamais pour décider de naviguer.']);$('insightContent').innerHTML=items.slice(0,3).map(([icon,title,detail])=>`<div class="insight-row"><div class="insight-bubble">${ico(icon)}</div><div><strong>${safe(title)}</strong><p>${safe(detail)}</p></div></div>`).join('')}
function renderForecast(){if(!S.weather){$('dayButtons').innerHTML='';$('bigChart').innerHTML='<div class="empty-lite">Aucune prévision en direct disponible.</div>';$('hourlyTable').innerHTML='';$('weatherInsight').innerHTML='<p>Actualisez les données météo.</p>';$('marinePanel').innerHTML='<p>Données indisponibles.</p>';return}const dates=[...new Set(S.weather.hourly.time.map(t=>t.slice(0,10)))];if(S.day>=dates.length)S.day=0;$('dayButtons').innerHTML=dates.map((dt,i)=>`<button class="day-btn ${i===S.day?'active':''}" data-day="${i}">${i===0?'Aujourd’hui':i===1?'Demain':new Date(dt+'T12:00:00').toLocaleDateString('fr-FR',{weekday:'short'})}<span>${new Date(dt+'T12:00:00').toLocaleDateString('fr-FR',{day:'numeric',month:'short'})}</span></button>`).join('');$('dayButtons').querySelectorAll('[data-day]').forEach(b=>b.onclick=()=>{S.day=Number(b.dataset.day);renderForecast()});const indices=hourlyIndices();$('bigChart').innerHTML=makeChart(indices,true);$('hourlyTable').innerHTML=indices.map(i=>{const sc=scoreAt(i),h=S.weather.hourly;return`<div class="hour-card ${sc>=75?'ideal':''}"><div class="hour-top"><span>${hourAt(i)}</span><span>${sc}/100</span></div><div class="hour-weather">${fmt(h.temperature_2m?.[i])}°C · ${fmt(h.wind_speed_10m?.[i])} km/h<small>Pluie ${fmt(h.precipitation_probability?.[i])}% · ${scoreLabel(sc)}</small></div></div>`}).join('');const i=indices[Math.floor(indices.length/2)]??nowIndex(),h=S.weather.hourly,sun=dayBoundary(i);$('weatherInsight').innerHTML=[['Lever du soleil',sun?.sunrise||'—'],['Coucher du soleil',sun?.sunset||'—'],['Vent (milieu de journée)',fmt(h.wind_speed_10m?.[i])+' km/h'],['Pression atmosphérique',fmt(h.pressure_msl?.[i])+' hPa'],['Précipitations possibles',fmt(h.precipitation_probability?.[i])+' %'],['Modèle horaire','Open-Meteo · fuseau '+safe(S.weather.timezone||'local')]].map(([k,v])=>`<div class="reading-stat"><span>${safe(k)}</span><strong>${safe(v)}</strong></div>`).join('');renderMarinePanel(indices)}
function renderMarinePanel(indices){if(S.env!=='sea'){$('marinePanel').innerHTML='<p>Choisissez <strong>Mer & océan</strong> pour afficher les conditions marines modélisées.</p><p>Les profondeurs des fonds ne sont pas mesurées dans cette application.</p>';return}if(!S.marine){$('marinePanel').innerHTML='<p>Les données marines ne sont pas disponibles à cet endroit ou le service n’a pas répondu.</p>';return}const idx=indices[Math.floor(indices.length/2)]??nowIndex();const vals=[['Vagues significatives',getMarineAt(idx,'wave_height'),' m'],['Période des vagues',getMarineAt(idx,'wave_period'),' s'],['Houle',getMarineAt(idx,'swell_wave_height'),' m'],['Température surface mer',getMarineAt(idx,'sea_surface_temperature'),' °C'],['Courant océanique modélisé',getMarineAt(idx,'ocean_current_velocity'),' km/h'],['Niveau mer (réf. MSL)',getMarineAt(idx,'sea_level_height_msl'),' m']];$('marinePanel').innerHTML=vals.map(([k,v,u])=>`<div class="reading-stat"><span>${safe(k)}</span><strong>${v===null?'Indisponible':fmt(v,1)+safe(u)}</strong></div>`).join('')+'<p style="font-size:10px;margin-top:15px">Modèles à maille kilométrique, non adaptés à la navigation ni aux horaires réglementaires de marée. Vérifier les bulletins marins locaux.</p>'}
function renderTactics(){const sp=activeSpecies(),best=bestWindowText(),sc=scoreAt(nowIndex());const approach=$('tacticStyle').value;S.style=approach;const adaptation=approach==='boat'?'Depuis un bateau : prospecter les variations de relief avec prudence et sondeur si disponible.':approach==='wade'?'À pied dans l’eau : vérifier profondeur, courant, fond et possibilité de retour. Ne jamais s’engager en milieu dangereux.':'Depuis la rive : rechercher les postes accessibles et les cassures à portée de lancer.';const warn=(S.env==='sea'?'En mer : consulter les bulletins de sécurité, marées officielles, zones interdites et limites de prélèvement.':'En eau douce : vérifier catégorie du parcours, autorisation, ouverture, quotas et espèces protégées.')+' Les profondeurs ci-dessous sont des fourchettes de prospection, non des mesures du site.';
$('tacticResult').innerHTML=`<div class="tactic-details"><div class="strategy-hero"><div><span class="strategy-label">PLAN PERSONNALISÉ · ${safe(S.env==='sea'?'MER & OCÉAN':'EAU DOUCE')}</span><h2>${safe(sp.name)} · ${safe(sp.rig)}</h2><p>${safe(sp.approach)}. ${safe(adaptation)}</p></div><div class="strategy-number">${sc??'—'}<small>INDICE ACTUEL /100</small></div></div><section class="panel strategy-panel"><div class="panel-title"><div><span class="section-eyebrow">STRATÉGIE DE TERRAIN</span><h3>Votre protocole de prospection</h3></div></div><div class="strategy-list">${[['target','Où prospecter',sp.approach],['waves','Profondeur à tester (indicative)',sp.depth],['activity','Technique principale',sp.rig],['sunrise','Quand commencer',best.time==='—'?'Consultez les prévisions':best.time+' · '+best.desc],['shield-check','Approche terrain',sp.note]].map(([ic,k,v])=>`<div class="strategy-attribute"><div class="mark">${ico(ic)}</div><div><strong>${safe(k)}</strong><p>${safe(v)}</p></div></div>`).join('')}</div></section><section class="panel strategy-panel"><div class="panel-title"><div><span class="section-eyebrow">MONTAGE & MATÉRIEL</span><h3>Le montage recommandé</h3></div></div><div class="rig-picture">${rigDiagram()}</div><div class="strategy-list">${[['target','Montage',sp.rig],['waves','Corps de ligne / bas de ligne',sp.line],['fish','Leurres et appâts',sp.bait],['anchor','Hameçon / lest',sp.hook]].map(([ic,k,v])=>`<div class="strategy-attribute"><div class="mark">${ico(ic)}</div><div><strong>${safe(k)}</strong><p>${safe(v)}</p></div></div>`).join('')}</div><div class="warning-box">${safe(warn)}</div></section></div>`}
function rigDiagram(){return`<svg viewBox="0 0 400 115" xmlns="http://www.w3.org/2000/svg" role="img" aria-label="Schéma conceptuel simplifié d'un montage de pêche"><path d="M13 37H141" stroke="#3e8890" stroke-width="2" stroke-dasharray="6 5"/><circle cx="151" cy="37" r="8" fill="none" stroke="#0b9f94" stroke-width="3"/><path d="M158 37H277" stroke="#3e8890" stroke-width="2"/><circle cx="281" cy="37" r="4" fill="#0b9f94"/><path d="M281 41v37" stroke="#3e8890" stroke-width="2"/><path d="M281 78c-7 10 2 23 12 11" fill="none" stroke="#0c5a68" stroke-width="3" stroke-linecap="round"/><path d="m293 89-5 0" stroke="#0c5a68" stroke-width="3"/><path d="M238 37v29" stroke="#3e8890" stroke-width="2"/><path d="M230 66h16l-8 16Z" fill="#6dbab6"/><g fill="#7a929d" font-family="sans-serif" font-size="10"><text x="13" y="23">CORPS DE LIGNE</text><text x="123" y="19">NŒUD</text><text x="203" y="19">BAS DE LIGNE</text><text x="252" y="107">HAMEÇON</text><text x="205" y="98">LEST</text></g></svg>`}
function renderJournal(){const entries=S.journal;$('journalCount').textContent=entries.length;$('catchCount').textContent=entries.reduce((a,e)=>a+Math.max(0,Number(e.count)||0),0);$('journalItems').innerHTML=entries.length?entries.slice().reverse().map((j,index)=>`<div class="journal-entry"><div><strong>${safe(j.place||'Sortie de pêche')}</strong><small>${safe(j.date||'—')} · ${safe(j.species||'Espèce non précisée')}</small><p>${safe(j.notes||'Aucune note')} ${j.depth?'· Profondeur '+safe(j.depth):''}</p></div><div style="display:flex;align-items:center;gap:10px"><span class="journal-count">${Math.max(0,Number(j.count)||0)} prise(s)</span><button class="icon-button" style="height:30px;width:30px" title="Supprimer cette sortie" data-delete-journal="${entries.length-1-index}">${ico('trash')}</button></div></div>`).join(''):'<div class="journal-empty"><div class="journal-empty-icon">'+ico('book-open')+'</div><strong>Votre histoire de pêche commence ici.</strong><br>Enregistrez votre première sortie, vos observations et vos prises.<br>Les données restent sur cet appareil.</div>';$('journalItems').querySelectorAll('[data-delete-journal]').forEach(b=>b.onclick=()=>{const idx=Number(b.dataset.deleteJournal);if(confirm('Supprimer cette sortie du carnet ?')){S.journal.splice(idx,1);saveJournal();renderJournal()}})}
function saveJournal(){try{localStorage.setItem('fishora_journal_v1',JSON.stringify(S.journal))}catch{toast('Stockage local indisponible : exportez vos données.')}}
function showLogModal(){const date=new Date().toISOString().slice(0,10);openModal(`<span class="section-eyebrow">CARNET DE PÊCHE</span><h2>Nouvelle sortie</h2><p>Enregistrez les observations réelles : elles seront conservées localement sur cet appareil.</p><form id="journalForm"><div class="field-row"><div class="field"><label for="logDate">Date</label><input id="logDate" type="date" value="${date}" class="text-input" required></div><div class="field"><label for="logCount">Nombre de prises</label><input id="logCount" type="number" min="0" max="9999" value="0" class="text-input" required></div></div><div class="field"><label for="logPlace">Lieu</label><input id="logPlace" class="text-input" maxlength="140" value="${safe(S.place)}" required></div><div class="field-row"><div class="field"><label for="logFish">Espèce</label><input id="logFish" class="text-input" maxlength="80" value="${safe(activeSpecies().name)}"></div><div class="field"><label for="logDepth">Profondeur observée (facultatif)</label><input id="logDepth" class="text-input" maxlength="50" placeholder="Ex. 3 m"></div></div><div class="field"><label for="logNotes">Observations : montage, appât, conditions</label><textarea id="logNotes" class="text-area" maxlength="2000" placeholder="Ex. prises près de la cassure, leurre souple de 8 cm…"></textarea></div><button class="primary-small" type="submit">${ico('check')} Enregistrer ma sortie</button></form>`);$('journalForm').onsubmit=e=>{e.preventDefault();const count=Number($('logCount').value);if(!Number.isInteger(count)||count<0||count>9999){toast('Nombre de prises invalide.');return}const entry={date:$('logDate').value,place:$('logPlace').value.trim(),species:$('logFish').value.trim(),count,depth:$('logDepth').value.trim(),notes:$('logNotes').value.trim(),lat:Number(S.lat.toFixed(5)),lon:Number(S.lon.toFixed(5))};if(!entry.date||!entry.place){toast('Date et lieu requis.');return}S.journal.push(entry);saveJournal();closeModal();renderJournal();toast('Sortie enregistrée dans votre carnet')}}
function exportJournal(){const data=JSON.stringify({application:'FISHORA',version:1,exported_at:new Date().toISOString(),entries:S.journal},null,2),file=new Blob([data],{type:'application/json'}),url=URL.createObjectURL(file);const a=document.createElement('a');a.href=url;a.download='fishora-carnet-'+new Date().toISOString().slice(0,10)+'.json';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),6000);toast('Export JSON demandé au navigateur')}
function distanceKm(a,b,c,d){const rad=Math.PI/180,dLat=(c-a)*rad,dLon=(d-b)*rad;const q=Math.sin(dLat/2)**2+Math.cos(a*rad)*Math.cos(c*rad)*Math.sin(dLon/2)**2;return 12742*Math.asin(Math.sqrt(q))}
function spotInterest(tags){
if(tags.leisure==='fishing')return {rank:3,label:'Pêche référencée',why:'Secteur associé à la pêche dans OpenStreetMap, sans garantie d’accès.'};
if(tags.man_made==='pier'||tags.man_made==='breakwater'||tags.natural==='cape'||tags.natural==='reef')return {rank:2,label:'Structure à explorer',why:'Relief ou ouvrage cartographié : recherchez courant, sécurité et accès sur place.'};
if(tags.waterway==='river'||tags.natural==='bay')return {rank:1,label:'Milieu à reconnaître',why:'Milieu aquatique cartographié : aucune présence de poisson certifiée.'};
return {rank:0,label:'Zone candidate',why:'Plan d’eau ou secteur cartographique à vérifier sur place.'};
}
function spotType(tags){if(tags.leisure==='fishing')return'Lieu de pêche cartographié';if(tags.waterway==='river')return'Rivière';if(tags.waterway==='stream')return'Cours d’eau';if(tags.waterway==='canal')return'Canal';if(tags.natural==='beach')return'Plage';if(tags.man_made==='pier')return'Jetée';if(tags.natural==='bay')return'Baie';if(tags.leisure==='marina')return'Port / marina';if(tags.man_made==='breakwater')return'Digue / brise-lames';if(tags.natural==='reef')return'Récif';if(tags.natural==='cape')return'Cap / pointe';if(tags.water==='reservoir')return'Réservoir';return'Lac / plan d’eau'}
async function loadSpots(){const seq=++S.spotFetchCounter;S.spots=[];renderHomeSpots();$('spotList').innerHTML='<div class="empty-lite">Lecture de la cartographie OpenStreetMap…</div>';$('spotCount').textContent='…';const radius=Number($('spotRadius').value),lat=S.lat,lon=S.lon;const ar=`around:${radius},${lat.toFixed(6)},${lon.toFixed(6)}`;const water=S.env==='sea'?`nwr(${ar})["natural"="beach"];nwr(${ar})["natural"="bay"];nwr(${ar})["man_made"="pier"];nwr(${ar})["leisure"="marina"];nwr(${ar})["man_made"="breakwater"];nwr(${ar})["natural"="cape"];nwr(${ar})["leisure"="fishing"];`:`nwr(${ar})["natural"="water"]["name"];nwr(${ar})["waterway"~"^(river|canal|stream)$"]["name"];nwr(${ar})["leisure"="fishing"];`;const query=`[out:json][timeout:22];(${water});out center 100;`;
try{const url='https://overpass.kumi.systems/api/interpreter?data='+encodeURIComponent(query);let response;try{response=await fetchTimed(url,23000)}catch{response=await fetchTimed('https://overpass-api.de/api/interpreter?data='+encodeURIComponent(query),23000)}const data=await response.json();if(seq!==S.spotFetchCounter)return;const unique=new Set();const entries=[];for(const el of data.elements||[]){const x=el.lat??el.center?.lat,y=el.lon??el.center?.lon;if(!Number.isFinite(x)||!Number.isFinite(y))continue;const tags=el.tags||{},type=spotType(tags),name=tags.name||tags['name:fr']||((tags.leisure==='fishing')?'Zone de pêche (OSM)':null);if(!name)continue;const dist=distanceKm(lat,lon,x,y);if(dist>radius/1000*1.6)continue;const key=name.toLowerCase().replace(/\W/g,'').slice(0,35)+':'+(Math.round(x*1000))+':'+(Math.round(y*1000));if(unique.has(key))continue;unique.add(key);entries.push({id:`${el.type}-${el.id}`,name,type,lat:x,lon:y,distance:dist,verified:tags.leisure==='fishing',interest:spotInterest(tags)})}entries.sort((a,b)=>b.interest.rank-a.interest.rank||a.distance-b.distance);S.spots=entries.slice(0,50);renderSpots();renderHomeSpots();syncMap(false)}catch(e){if(seq!==S.spotFetchCounter)return;S.spots=[];$('spotList').innerHTML='<div class="empty-lite">Recherche cartographique momentanément indisponible, ou aucun secteur identifié. Vous pouvez placer un repère en cliquant sur la carte.</div>';$('spotCount').textContent='0';renderHomeSpots();syncMap(false)}}
async function loadObservations(){const seq=++S.observationFetchCounter;S.observations=[];S.observationState='loading';renderObservations();renderLocalExpert();const url=`https://api.inaturalist.org/v1/observations/species_counts?lat=${encodeURIComponent(S.lat)}&lng=${encodeURIComponent(S.lon)}&radius=25&iconic_taxa=Actinopterygii&quality_grade=research&per_page=30&locale=fr`;
try{const r=await fetchTimed(url,15000);const j=await r.json();if(seq!==S.observationFetchCounter)return;S.observations=(j.results||[]).filter(x=>x.taxon?.name).slice(0,30).map(x=>({name:x.taxon.preferred_common_name||x.taxon.name,latin:x.taxon.name,count:x.count||0}));S.observationState='ready';renderObservations();renderLocalExpert()}catch{if(seq!==S.observationFetchCounter)return;S.observations=[];S.observationState='error';renderObservations(true);renderLocalExpert()}}
function renderObservations(error=false){const p=$('observedSpecies');if(!p)return;const url=`https://www.inaturalist.org/observations?lat=${encodeURIComponent(S.lat)}&lng=${encodeURIComponent(S.lon)}&radius=25&iconic_taxa=Actinopterygii`;$('inatLink').href=url;if(S.observations.length){p.innerHTML=S.observations.slice(0,12).map(s=>`<div class="observed-item"><strong>${safe(s.name)}</strong><small>${safe(s.latin)}</small><span class="obs-count">${fmt(s.count)} observation(s)</span></div>`).join('')}else p.innerHTML=`<div class="empty-lite">${error?'Service de biodiversité indisponible.':'Aucune observation vérifiée retournée pour ce secteur. Vous pouvez consulter iNaturalist directement.'}</div>`}
const SPECIES_TAXA={
 perch:['Perca fluviatilis','Perca flavescens'],zander:['Sander lucioperca'],pike:['Esox lucius'],
 carp:['Cyprinus carpio'],trout:['Salmo trutta','Oncorhynchus mykiss','Salvelinus fontinalis'],
 catfish:['Silurus glanis'],bass:['Micropterus salmoides','Micropterus dolomieu'],
 salmon:['Salmo salar'],barbel:['Barbus barbus'],seabass:['Dicentrarchus labrax'],
 seabream:['Sparus aurata'],mackerel:['Scomber scombrus'],pollack:['Pollachius pollachius'],
 tuna:['Thunnus thynnus','Thunnus albacares'],snapper:['Lutjanus campechanus','Lutjanus griseus'],
 grouper:['Epinephelus marginatus','Epinephelus malabaricus'],bonefish:['Albula vulpes'],
 tarpon:['Megalops atlanticus'],barramundi:['Lates calcarifer'],
 snook:['Centropomus undecimalis'],gt:['Caranx ignobilis'],mahimahi:['Coryphaena hippurus']};
function localMatches(){const mapped=[];for(const o of S.observations){for(const [id,names] of Object.entries(SPECIES_TAXA)){if(names.some(n=>o.latin.toLowerCase()===n.toLowerCase())){const sp=SPECIES.find(s=>s.id===id);if(sp&&(sp.env===S.env||sp.env==='both')&&!mapped.some(x=>x.id===id))mapped.push({id,name:sp.name,latin:o.latin,count:o.count});break}}}return mapped}
function renderLocalExpert(){const e=$('worldExpert');if(!e)return;
 const available=S.observationState==='ready',matches=localMatches();const seen=S.observations.length;
 $('localEvidence').textContent=S.example?'DESTINATION DÉMO':available?(seen?'DONNÉES NATURALISTES':'COUVERTURE LIMITÉE'):S.observationState==='error'?'SOURCE INDISPONIBLE':'ANALYSE EN COURS';
 $('localPositionNote').textContent=`${S.place} · ${S.env==='sea'?'Mer / littoral':'Eau douce'} · fuseau horaire local automatique. Informations de biodiversité recherchées dans un rayon de 25 km.`;
 if(matches.length){$('localSpecies').innerHTML=`<p class="local-muted">Espèces observées identifiées parmi nos fiches techniques :</p><div class="local-fish-chips">${matches.slice(0,5).map(m=>`<button data-local-target="${safe(m.id)}" class="local-fish-chip ${m.id===S.species?'active':''}"><span>${safe(m.name)}</span><small>${fmt(m.count)} obs.</small></button>`).join('')}</div><p class="local-caption">Cliquez sur une espèce pour adapter les horaires et montages. Observations historiques, pas preuve de population actuelle.</p>`}
 else if(available&&seen){$('localSpecies').innerHTML=`<p class="local-muted">${seen} taxons répertoriés dans les premiers résultats locaux ; aucune correspondance certaine avec notre bibliothèque de montages.</p><div class="local-taxa">${S.observations.slice(0,3).map(o=>`<span>${safe(o.name)}</span>`).join('')}</div><p class="local-caption">Explorez la liste d'observations ; les techniques non documentées ne sont pas extrapolées.</p>`}
 else {$('localSpecies').innerHTML=`<p class="local-muted">${S.observationState==='error'?'Source iNaturalist momentanément indisponible.':available?'Aucun poisson documenté par la recherche locale.':'Recherche d’observations en cours…'}</p><p class="local-caption">L’absence de données n’est pas une preuve d’absence de poissons.</p>`}
 const sp=activeSpecies(),best=bestWindowText();
 $('localStrategy').innerHTML=`<strong>${safe(sp.name)} · ${safe(sp.rig)}</strong><p>${safe(sp.approach)}.</p><div class="local-strategy-spec"><span>Profondeur à tester</span><b>${safe(sp.depth)}</b></div><div class="local-strategy-spec"><span>Meilleur créneau prévu</span><b>${safe(best.time)} ${safe(best.desc)}</b></div><p class="local-caption">Profondeur indicative par espèce, non bathymétrique. ${matches.some(x=>x.id===sp.id)?'Espèce également signalée localement par iNaturalist.':'Présence de cette espèce non validée localement.'}</p>`;
 const legalQuery=`${S.place} official fishing regulations license permit seasons bag limits protected areas`;const legalUrl='https://www.google.com/search?q='+encodeURIComponent(legalQuery);
 $('localLegalLink').href=legalUrl;
 $('localLegal').innerHTML=`<div class="local-check">${ico('check')} Licence, permis et droits d’accès</div><div class="local-check">${ico('check')} Saisons, tailles, quotas et espèces protégées</div><div class="local-check">${ico('check')} Réserves, risques météo et conditions marines</div><p class="local-caption">Lien vers une recherche de sources officielles : aucune conformité juridique vérifiée automatiquement pour ce lieu.</p>`;
 e.querySelectorAll('[data-local-target]').forEach(b=>b.onclick=()=>{const id=b.dataset.localTarget;const sp=SPECIES.find(x=>x.id===id);if(!sp)return;S.species=id;updateSelectors();renderAll();toast(`Plan actualisé pour ${sp.name} · espèce observée dans la région`)});
}
function renderSpots(){$('spotCount').textContent=S.spots.length;$('spotList').innerHTML=S.spots.length?S.spots.map((s,i)=>`<div class="spot-item ${S.selectedSpot?.id===s.id?'active':''}" data-spot="${i}"><div class="spot-type-icon">${ico(s.verified?'fish':'waves')}</div><div class="spot-info"><strong>${safe(s.name)}</strong><small>${safe(s.type)} · ${fmt(s.distance,1)} km</small></div><div class="spot-tag">${safe(s.interest?.label||'Candidat')}</div></div>`).join(''):'<div class="empty-lite">Aucun secteur identifié dans ce rayon. Cliquez sur la carte pour placer manuellement un repère.</div>';$('spotList').querySelectorAll('[data-spot]').forEach(b=>b.onclick=()=>{const sp=S.spots[Number(b.dataset.spot)];S.selectedSpot=sp;renderSpots();if(S.map){S.map.setView([sp.lat,sp.lon],13)}showSpotDetail(sp)})}
function showSpotDetail(sp){const html=`<span class="section-eyebrow">SECTEUR CARTOGRAPHIQUE</span><h2>${safe(sp.name)}</h2><p>${safe(sp.type)} · à ${fmt(sp.distance,1)} km du repère précédent. ${safe(sp.interest?.why||'Secteur à vérifier, pas un spot de capture confirmé.')}</p><div class="modal-help">${safe(fmt(sp.lat,5))}°, ${safe(fmt(sp.lon,5))}° · Aucun relevé fiable de bathymétrie ou de présence de poissons à cette coordonnée.</div><div style="display:flex;gap:10px;flex-wrap:wrap;margin-top:20px"><button id="spotAnalysis" class="primary-small">${ico('target')} Analyser ici</button><button id="spotFav" class="secondary-button">${ico('check')} ${S.favs.includes(sp.id)?'Favori enregistré':'Enregistrer le favori'}</button><a class="secondary-button" style="text-decoration:none" href="https://www.google.com/maps/search/?api=1&query=${sp.lat},${sp.lon}" target="_blank" rel="noopener">${ico('map-pin')} Itinéraire</a></div>`;openModal(html);$('spotAnalysis').onclick=()=>chooseLocation(sp.lat,sp.lon,sp.name);$('spotFav').onclick=()=>{if(!S.favs.includes(sp.id))S.favs.push(sp.id);else S.favs=S.favs.filter(id=>id!==sp.id);try{localStorage.setItem('fishora_fav_v1',JSON.stringify(S.favs))}catch{}closeModal();toast('Favoris mis à jour sur cet appareil')}}
function initMap(){if(S.map){setTimeout(()=>S.map.invalidateSize(),100);syncMap(false);return}if(typeof L==='undefined'){$('map').innerHTML='<div style="padding:60px 20px;text-align:center;color:#51707c">Carte interactive indisponible sans la bibliothèque Leaflet. Les autres fonctions restent utilisables.</div>';return}S.map=L.map('map',{zoomControl:false}).setView([S.lat,S.lon],11);L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{attribution:'© OpenStreetMap contributors',maxZoom:19}).addTo(S.map);L.control.zoom({position:'bottomright'}).addTo(S.map);S.map.on('click',e=>{const {lat,lng}=e.latlng;openModal(`<span class="section-eyebrow">REPÈRE PERSONNALISÉ</span><h2>Analyser ce point ?</h2><p>Latitude : ${fmt(lat,5)}° · Longitude : ${fmt(lng,5)}°. Les informations de pêche réelles ne sont pas garanties à cette coordonnée.</p><button id="analyzePoint" class="primary-small" style="margin-top:15px">${ico('target')} Prévoir la pêche ici</button>`);$('analyzePoint').onclick=()=>chooseLocation(lat,lng,`Repère personnalisé · ${fmt(lat,3)}°, ${fmt(lng,3)}°`)});syncMap(true);setTimeout(()=>S.map.invalidateSize(),180)}
function syncMap(zoom){if(!S.map)return;S.mapMarkers.forEach(m=>S.map.removeLayer(m));S.mapMarkers=[];if(S.mapCurrent)S.map.removeLayer(S.mapCurrent);const own=L.divIcon({className:'',html:'<div class="pin-dot"></div>',iconSize:[15,15],iconAnchor:[7,7]});S.mapCurrent=L.marker([S.lat,S.lon],{icon:own,zIndexOffset:200}).addTo(S.map).bindPopup('<strong>'+safe(S.place)+'</strong><br>Point météo sélectionné');for(const sp of S.spots){const marker=L.marker([sp.lat,sp.lon],{icon:L.divIcon({className:'',html:'<div class="pin-spot"></div>',iconSize:[12,12],iconAnchor:[6,6]})}).addTo(S.map);marker.bindPopup(`<strong>${safe(sp.name)}</strong><br>${safe(sp.type)}<br><span style="color:#75929a">Secteur candidat, pas un spot vérifié</span><br><button class="map-pop-action" data-pick="${safe(sp.id)}">Détails / analyser</button>`);S.mapMarkers.push(marker)}S.map.off('popupopen');S.map.on('popupopen',e=>{const btn=e.popup.getElement()?.querySelector('[data-pick]');if(btn)btn.onclick=()=>{const sp=S.spots.find(p=>p.id===btn.dataset.pick);if(sp)showSpotDetail(sp)}});if(zoom)S.map.setView([S.lat,S.lon],11);setTimeout(()=>S.map.invalidateSize(),100)}
function showAbout(){openModal(`<span class="section-eyebrow">FISHORA · TRANSPARENCE</span><h2>Données, précision & limites</h2><p>FISHORA V1.1 est une application personnelle de planification, pas un service de guidage nautique, un sondeur, ni un registre de pêche réglementaire mondial.</p><ul class="about-list"><li><strong>Météo mondiale :</strong> prévisions et mesures modélisées par <a href="https://open-meteo.com/" target="_blank" rel="noopener">Open-Meteo</a>, mises à jour par le fournisseur.</li><li><strong>Mer :</strong> modèles de vagues, courants, température de surface et niveau de mer via <a href="https://open-meteo.com/en/docs/marine-weather-api" target="_blank" rel="noopener">Open-Meteo Marine</a>. Ils ne remplacent ni les marées officielles, ni les cartes marines.</li><li><strong>Observations naturalistes :</strong> données publiques <a href="https://www.inaturalist.org/" target="_blank" rel="noopener">iNaturalist</a> dans un rayon de 25 km. Ce ne sont pas des observations de captures ni des preuves d'accès à la pêche.</li><li><strong>Cartes et secteurs :</strong> <a href="https://www.openstreetmap.org/" target="_blank" rel="noopener">© OpenStreetMap contributors</a> via Overpass. L'existence d'un plan d'eau n'est pas une preuve de poisson ni d'accès légal.</li><li><strong>Indice /100 :</strong> heuristique éditoriale, calculée d'après vent, rafales, précipitations, nébulosité, pression, luminosité et, en mer, vagues. Ni probabilité scientifique de capture, ni donnée issue de captures historiques.</li><li><strong>Profondeurs :</strong> plages génériques de prospection par espèce, jamais une profondeur mesurée.</li><li><strong>Règles de pêche :</strong> permis, espèces, tailles, quotas, réserves et accès à vérifier auprès des autorités locales avant chaque sortie.</li><li><strong>Données privées :</strong> journal et favoris dans le stockage du navigateur. Aucun compte ni serveur FISHORA. La géolocalisation est transmise aux fournisseurs des données si vous l'utilisez.</li><li><strong>Usage :</strong> API Open-Meteo gratuite pour usage non commercial, avec attribution ; tout déploiement commercial nécessite une vérification des licences.</li></ul><div class="modal-help">Sécurité : aucune recommandation de pêche ne constitue une validation des conditions de navigation, de baignade ou de wading. En cas d'orage, houle ou courant dangereux, ne pas s'engager.</div>`)}
function renderAll(){renderMetrics();renderHomeChart();renderHomeTactics();renderHomeSpots();renderInsights();renderObservations();renderLocalExpert();if(S.page==='forecast'||S.weather)renderForecast();if(S.page==='tactics')renderTactics();renderJournal()}
function bind(){hydrateIcons();updateSelectors();document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>page(b.dataset.page));document.querySelectorAll('[data-goto]').forEach(b=>b.onclick=()=>page(b.dataset.goto));$('changeLocation').onclick=showLocation;$('geoPrimary').onclick=geoLocate;$('mapGeo').onclick=geoLocate;$('refreshBtn').onclick=()=>{loadWeather();loadSpots()};$('methodBtn').onclick=showAbout;$('closeModal').onclick=closeModal;$('modalBackdrop').onclick=e=>{if(e.target===$('modalBackdrop'))closeModal()};document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal()});document.querySelectorAll('#waterMode button').forEach(b=>b.onclick=()=>setEnv(b.dataset.env));$('spotRadius').onchange=loadSpots;$('reloadSpots').onclick=loadSpots;for(const select of ['homeSpecies','forecastSpecies','tacticSpecies']){$(select).onchange=e=>{S.species=e.target.value;for(const n of ['homeSpecies','forecastSpecies','tacticSpecies'])$(n).value=S.species;renderAll()}}$('tacticStyle').onchange=()=>renderTactics();$('generatePlan').onclick=()=>{renderTactics();toast('Plan technique mis à jour')};$('openLog').onclick=showLogModal;$('exportJournal').onclick=exportJournal;const now=new Date();$('todayTop').textContent=now.toLocaleDateString('fr-FR',{weekday:'long',day:'numeric',month:'long',year:'numeric'});$('miniPlace').textContent=S.place.toUpperCase();renderAll();loadWeather();loadSpots();loadObservations();if(window.isSecureContext&&navigator.permissions?.query){navigator.permissions.query({name:'geolocation'}).then(v=>{if(v.state==='granted')geoLocate()}).catch(()=>{})}}
document.addEventListener('DOMContentLoaded',bind);
